  notifDhikrTitle: ["{{timeOfDay}} dhikr", "ذكر {{timeOfDay}}", "{{timeOfDay}} کا ذکر", "{{timeOfDay}}-এর জিকির", "Зикр ({{timeOfDay}})", "Dhikr du {{timeOfDay}}", "{{timeOfDay}} 짐르"],
