// eslint-disable-next-line no-console
const ORDER = ['en', 'ar', 'ur', 'bn', 'ru', 'fr', 'ko'];

const results = {};
for (const locale of ORDER) {
  const path = FILES[locale];
  const json = JSON.parse(readFileSync(path, 'utf8'));
  const before = Object.keys(json).length;
  let added = 0;
  for (const [key, translations] of Object.entries(K)) {
    const value = translations[ORDER.indexOf(locale)];
    if (value === undefined) throw new Error(`Missing ${locale} translation for ${key}`);
    if (!(key in json)) {
      json[key] = value;
      added++;
    }
  }
  writeFileSync(path, JSON.stringify(json, null, 2) + '\n');
  results[locale] = { before, after: Object.keys(json).length, added };
}

console.log('Injected keys per locale:');
for (const [locale, r] of Object.entries(results)) {
  console.log(`  ${locale}: ${r.before} -> ${r.after} (+${r.added})`);
}

// Parity check
const keySets = {};
for (const locale of ORDER) {
  keySets[locale] = new Set(Object.keys(JSON.parse(readFileSync(FILES[locale], 'utf8'))));
}
const sizes = ORDER.map(l => keySets[l].size);
if (new Set(sizes).size !== 1) {
  console.error('PARITY FAIL — sizes differ:', Object.fromEntries(ORDER.map(l => [l, keySets[l].size])));
  process.exit(1);
}
const baseSet = keySets.en;
let allEqual = true;
for (const locale of ORDER.slice(1)) {
  for (const k of baseSet) if (!keySets[locale].has(k)) { console.error(`${locale} missing: ${k}`); allEqual = false; }
  for (const k of keySets[locale]) if (!baseSet.has(k)) { console.error(`${locale} extra: ${k}`); allEqual = false; }
}
console.log(allEqual ? `PARITY OK — ${sizes[0]} keys in all 7 locales` : 'PARITY FAIL');
process.exit(allEqual ? 0 : 1);
